#define MG_ENABLE_SOCKET 0
#define MG_ENABLE_LOG 1
#define MG_ENABLE_LINES 1
#define MG_ENABLE_TCPIP 1

#include "mongoose.c"
#include "driver_mock.c"

static void fn(struct mg_connection *c, int ev, void *ev_data, void *fn_data) {
  struct mg_http_serve_opts opts = {.root_dir = "."};
  if (ev == MG_EV_HTTP_MSG) {
    MG_INFO(("MG_EV_HTTP_MSG received"));
    mg_http_serve_dir(c, (struct mg_http_message *) ev_data, &opts);
  }
  (void) fn_data;
}

int main(int argc, char *argv[]) {
  if (argc > 1) {
    size_t len = 0;
    char *buf = mg_file_read(&mg_fs_posix, argv[1], &len);
    if (buf != NULL) {
      mg_log_set(MG_LL_DEBUG);
      struct mg_tcpip_if mif = {.ip = 0x01020304,
                                .mask = 255,
                                .gw = 0x01010101,
                                .driver = &mg_tcpip_driver_mock};
      struct mg_mgr mgr;
      mg_mgr_init(&mgr);
      mg_tcpip_init(&mgr, &mif);

      const char *url = "http://localhost:12345";
      struct mg_connection *c = mg_http_connect(&mgr, url, fn, NULL);
      MG_INFO(("c = %p", (void *) c));
      if (c != NULL) {
        mg_iobuf_add(&c->recv, 0, (uint8_t *) buf, len);
        MG_INFO(("recv.len = %d", (int) c->recv.len));
        c->pfn(c, MG_EV_READ, NULL, NULL);
      }
      mg_mgr_free(&mgr);
      mg_tcpip_free(&mif);
      free(buf);
    }
  }
  return 0;
}
EOF
